const h = `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>سجل التغطية التفصيلي · ساري</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="feature-audit.css"><script src="feature-audit.js" defer></script></head><body class="feature-audit"><header><a href="./#/page/merchant/virtual-team">← افتح الموك أب</a><p class="eyebrow">لقطة المصدر ${sourceDate}</p><h1>كل صفحة، وما بداخلها</h1><p>سجل تدقيق قابل للبحث من لقطة المصدر المسجلة. «محصور» تعني أنه لم يسقط من الفحص؛ لا تعني أن تصميمه اكتمل أو أن تشغيله نجح.</p><div class="audit-stats"><strong>${stats.routes} مسارًا</strong><strong>${stats.files} ملف واجهة</strong><strong>${stats.controls} عنصر تحكم في المصدر</strong><strong>${stats.choices} قائمة خيارات</strong></div></header><section class="audit-toolbar"><label for="audit-search">ابحث بصفحة أو خاصية<input id="audit-search" placeholder="مثل: الخصم، الصوت، المراجعة، الدوام…"></label><label for="audit-filter">حالة التصميم<select id="audit-filter"><option value="all">كل الصفحات</option><option value="عام">الموك أب العام</option><option value="تفصيلي">التصميم التفصيلي</option><option value="توجيه">إعادة التوجيه</option></select></label><p id="audit-count" role="status">${coverage.length} صفحة</p></section><main>${coverage.map(r => `<details class="audit-page" data-design="${e(r.design)}"><summary><span><strong>${e(r.title)}</strong><small dir="ltr">${e(r.route)}</small></span><span>${r.controls.length} عنصر · ${e(r.design)}</span></summary><div class="audit-page-body"><p><a href="./#/page${e(r.route)}">افتح تصميم الصفحة ←</a>${r.redirect ? ` · يحوّل إلى ${e(r.redirect)}` : ""}</p>${r.gaps.map(g => `<p class="audit-gap">${e(g)}</p>`).join("")}<h2>خطة المطابقة</h2><p>${e(r.acceptancePlan)}</p>${r.designSections.length ? `<ul>${r.designSections.map(s => `<li>${e(s)}</li>`).join("")}</ul>` : ""}<h2>إجراءات النظام المرتبطة</h2><p dir="ltr" class="audit-apis">${e(r.mutations.join(" · ") || "لا توجد تعديلات مباشرة في المكونات المحصورة")}</p><h2>قراءات النظام المرتبطة</h2><p dir="ltr" class="audit-apis">${e(r.queries.join(" · ") || "لا توجد قراءات مباشرة محصورة")}</p>${r.imperativeReads?.length ? `<p class="audit-hint">${r.imperativeReads.length} قراءة برمجية؛ تُتبع دوال القراءة ومراجعها، وتبقى القراءة غير المحسومة مرشحة للمراجعة.</p>` : ""}${r.browserRequests?.length ? `<h2>طلبات المتصفح المباشرة</h2><ul>${r.browserRequests.map(call => `<li><code dir="ltr">${e(call.method)} ${e(call.target || call.targetExpression)}</code> · ${e(call.file)}:${call.line}</li>`).join("")}</ul>` : ""}<h2>الحقول والأزرار والنوافذ</h2><p class="audit-hint">القوائم الديناميكية تُظهر موضعها ومصدرها؛ مراجعتها لا تُستبدل بعدّ عناصر JSX.</p><div class="audit-controls">${r.controlDetails.map(c => `<article><b>${e(c.label || c.binding?.slice(0, 110) || c.tag)}</b><p>${e(c.section)}</p><small dir="ltr">${e(c.file)}:${c.line}</small><small>${e(c.tag)}${c.required ? " · مطلوب" : ""}${c.min ? ` · الحد الأدنى ${e(c.min)}` : ""}${c.max ? ` · الحد الأعلى ${e(c.max)}` : ""}${c.maxLength ? ` · طول ${e(c.maxLength)}` : ""}</small>${c.options.length ? `<p>الخيارات: ${c.options.map(o => e(o.label || o.value)).join("، ")}</p>` : ""}${c.conditions.length ? `<details><summary>شروط الظهور</summary><code dir="ltr">${e(c.conditions.join(" / "))}</code></details>` : ""}<span class="audit-source">محصور من المصدر · ليس نجاح اختبار وظيفي</span></article>`).join("") || "<p>صفحة تنقل أو تحويل؛ تفاصيل البطاقات ضمن قوائم الخيارات في السجل.</p>"}</div></div></details>`).join("")}</main><footer><h2>حدود الأدلة</h2><p>${stats.errorSignalMissing} من ${stats.queryCalls} استدعاء قراءة لا تظهر له إشارة معالجة خطأ مباشرة في التحليل الساكن. هذه إشارات للمراجعة، وليست جميعها أعطالًا مؤكدة. عناصر الشروط ${stats.conditions}. القراءات البرمجية ${stats.imperativeReads}، منها ${stats.unresolvedReads} لم يُحسم مصدرها. طلبات المتصفح المباشرة ${stats.browserRequests}؛ قد تشمل ملفات الأصول. ملفات الأدوات المحلية مشمولة؛ العناصر المحسوبة والصلاحيات وسلوك المزود تحتاج اختبارًا مستقلًا.</p><h2>ملفات قديمة غير متصلة بالمسارات</h2><ul>${inventory.orphanDetails.map(o => `<li><code>${e(o.file)}</code> · ${o.controls} عنصر · ${o.unmatchedApis.length ? `واجهات لا تظهر في الصفحات المرتبطة: ${e(o.unmatchedApis.join(", "))}` : "واجهاتها توجد أيضًا في المكونات المرتبطة"}</li>`).join("")}</ul><p>لم تُحذف هذه الملفات تلقائيًا، ولم يُعتبر وجودها دليلًا على وصول التاجر إليها.</p></footer></body></html>`;
